<script setup>
import {ref,onMounted,onUnmounted,nextTick} from 'vue'
import {api} from '../lib/api'
import {subjectMap} from '../data/quiz'
import {useMessages} from '../stores/messages'
import FriendInbox from '../components/FriendInbox.vue'
import GameHeader from '../components/GameHeader.vue'
const tab=ref('admin');const messages=useMessages(),items=ref([]),selected=ref(null),loading=ref(false),opening=ref(false),error=ref('');let interval,alive=true,request=0
async function load(){if(loading.value)return;loading.value=true;try{const result=await api('/messages');if(alive){items.value=result.items;await messages.refresh();error.value=''}}catch(e){if(alive)error.value=e.message}finally{if(alive)loading.value=false}}
async function open(id){const current=++request;opening.value=true;error.value='';try{const item=await api('/messages/'+id);if(!alive||current!==request)return;selected.value=item;replyText.value='';replyKey=crypto.randomUUID();await nextTick();if(!alive||current!==request)return;const ids=item.replies.filter(r=>!r.read_at&&r.senderRole!=='student').map(r=>r.id);if(ids.length){await api('/messages/'+id+'/read',{method:'POST',body:{replyIds:ids}});if(alive){for(const reply of selected.value?.replies??[])if(ids.includes(reply.id))reply.read_at=Date.now();await messages.refresh();await load()}}}catch(e){if(alive)error.value=e.message}finally{if(alive)opening.value=false}}
const replyText=ref(''),sending=ref(false);let replyKey=crypto.randomUUID()
async function sendReply(){if(sending.value||!replyText.value.trim())return;sending.value=true;try{await api('/messages/'+selected.value.id+'/reply',{method:'POST',body:{content:replyText.value,requestKey:replyKey}});replyText.value='';replyKey=crypto.randomUUID();await open(selected.value.id)}catch(e){error.value=e.message}finally{sending.value=false}}
async function remove(id){if(sending.value||!window.confirm('내 쪽지함에서 삭제할까요? 상대방의 쪽지는 유지됩니다.'))return;sending.value=true;try{await api('/messages/'+id,{method:'DELETE'});back();await messages.refresh()}catch(e){error.value=e.message}finally{sending.value=false}}
function back(){request++;selected.value=null;opening.value=false;load()}
function visibility(){if(document.visibilityState==='visible'){load();messages.refresh()}}
onMounted(()=>{document.documentElement.classList.add('mail-focus-mode');load();messages.refresh();interval=setInterval(visibility,15000);document.addEventListener('visibilitychange',visibility)})
onUnmounted(()=>{document.documentElement.classList.remove('mail-focus-mode');alive=false;clearInterval(interval);document.removeEventListener('visibilitychange',visibility);request++})
</script>
<template><section class="mail-page"><div class="mail-page-heading"><h1>내 쪽지함</h1><span>관리자와 친구에게 보내는 비공개 쪽지</span></div><div class="pet-study-menu"><RouterLink to="/pet" class="button light">← 파트너 돌보기</RouterLink><span class="mail-count">읽지 않은 답장 {{messages.unread}}개</span><button class="light" :disabled="loading" @click="selected?open(selected.id):load();messages.refresh()">{{loading?'불러오는 중…':'새로고침'}}</button></div><div class="mail-tabs"><button :class="{selected:tab==='admin'}" @click="tab='admin'">관리자 쪽지</button><button :class="{selected:tab==='friends'}" @click="tab='friends'">친구 · 쪽지함</button></div><FriendInbox v-if="tab==='friends'"/><template v-else><p v-if="error" class="notice" role="alert">{{error}}</p><p v-if="opening" role="status">쪽지를 불러오고 있어요…</p><section v-if="selected" class="panel private-thread"><button class="text-button" @click="back">← 내 쪽지함으로</button><div class="mail-meta"><span>{{subjectMap[selected.subject]?.name}}</span><span>{{selected.status==='answered'?'답변 완료':'답변 대기'}}</span><time>{{new Date(selected.created_at).toLocaleString('ko-KR',{timeZone:'Asia/Seoul'})}}</time></div><button class="text-button mail-delete" @click="remove(selected.id)">쪽지 삭제</button><h2>{{selected.title}}</h2><p v-if="!selected.fromAdmin" class="mail-body">{{selected.body}}</p><h3>{{selected.fromAdmin?'관리자에게 받은 쪽지':'대화 내용'}}</h3><p v-if="!selected.replies.length">아직 답변 대기 중이에요. 답장이 도착하면 알려 드릴게요.</p><article v-for="r in selected.replies" :key="r.id" class="mail-reply"><p><b>{{r.admin_name}} {{r.senderRole==='student'?'학생':'관리자'}}</b> · {{new Date(r.created_at).toLocaleString('ko-KR',{timeZone:'Asia/Seoul'})}}</p><p class="mail-body">{{r.body}}</p><small>{{r.read_at?'읽음':'읽음 확인 중'}}</small></article><form class="student-reply" @submit.prevent="sendReply"><label>관리자에게 답장<textarea v-model="replyText" required maxlength="5000" rows="3"/></label><button :disabled="sending||!replyText.trim()">{{sending?'전송 중…':'답장 보내기'}}</button></form></section><section v-else class="panel admin-mail-list"><h2>관리자와 주고받은 쪽지</h2><p v-if="!items.length&&!loading">아직 보낸 쪽지가 없어요. ‘질문있어요!’ 버튼으로 관리자에게 질문해 보세요.</p><div v-for="m in items" :key="m.id" class="mail-list-item"><div class="mail-meta"><span>{{subjectMap[m.subject]?.name}}</span><span :class="['review-badge',{completed:m.status==='answered'}]">{{m.status==='answered'?'답변 완료':'답변 대기'}}</span><b v-if="m.unread_count" class="unread-badge">새 답장 {{m.unread_count}}</b></div><button class="mail-subject-link" @click="open(m.id)">{{m.title}} →</button><button class="text-button mail-delete" @click="remove(m.id)">삭제</button><time>{{new Date(m.created_at).toLocaleString('ko-KR',{timeZone:'Asia/Seoul'})}}</time></div></section></template></section></template>
